/* ═══════════════════════════════════════════
   KING · servidor de partidas en línea
   Reparte las cartas, vigila los turnos y
   mantiene sincronizados a los cuatro jugadores.
   ═══════════════════════════════════════════ */
'use strict';

const express = require('express');
const http = require('http');
const { WebSocketServer } = require('ws');

const app = express();

/* La pantalla va incrustada aquí mismo, así el proyecto son
   archivos sueltos y se suben más fácil desde el teléfono. */
const PAGINA = '<!DOCTYPE html>\n<html lang="es">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">\n<meta name="apple-mobile-web-app-capable" content="yes">\n<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">\n<meta name="apple-mobile-web-app-title" content="KING CC">\n<meta name="theme-color" content="#0d4f2c">\n<link rel="apple-touch-icon" sizes="180x180" href="data:image/png;base64,">\n<link rel="apple-touch-icon-precomposed" sizes="180x180" href="data:image/png;base64,">\n<link rel="icon" type="image/png" href="data:image/png;base64,">\n<title>KING CC · en línea</title>\n<style>\n*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent;}\n:root{\n  --oro:#d8b45e; --rojo:#c62f2f; --tinta:#16202c;\n  --sombra:0 3px 10px rgba(0,0,0,.22);\n}\nhtml,body{height:100%;overflow:hidden;}\nbody{\n  font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',system-ui,sans-serif;\n  background:\n    repeating-linear-gradient(0deg,transparent,transparent 2px,rgba(0,0,0,.05) 2px,rgba(0,0,0,.05) 3px),\n    repeating-linear-gradient(90deg,transparent,transparent 2px,rgba(0,0,0,.05) 2px,rgba(0,0,0,.05) 3px),\n    radial-gradient(ellipse 70% 46% at 50% 40%,rgba(255,255,235,.13),transparent 70%),\n    radial-gradient(ellipse at 50% 40%,#1f8450,#0d4f2c 58%,#062b17);\n  color:#fff;display:flex;flex-direction:column;user-select:none;\n}\n.oculto{display:none!important;}\n\n/* ══ PANTALLAS DE ENTRADA ══ */\n.portada{\n  position:fixed;inset:0;z-index:200;display:flex;\n  align-items:center;justify-content:center;padding:20px;overflow:auto;\n}\n.panel{\n  background:rgba(6,32,18,.92);border:2px solid var(--oro);border-radius:24px;\n  padding:26px 22px;width:100%;max-width:420px;\n  box-shadow:0 16px 50px rgba(0,0,0,.45);\n}\n.franja-logo{\n  background:#fff;border-radius:18px;\n  margin:0 -6px 14px;padding:12px 0 10px;\n  display:flex;align-items:center;justify-content:center;\n  box-shadow:0 4px 16px rgba(0,0,0,.3),inset 0 -2px 0 rgba(0,0,0,.06);\n}\n.franja-logo img{display:block;width:92px;height:auto;}\n.palos-marca{font-size:26px;letter-spacing:8px;text-align:center;margin-bottom:6px;}\n.palos-marca .r{color:#e05a5a;}\n.panel h1{font-size:30px;font-weight:800;color:#f3dfae;letter-spacing:5px;text-align:center;}\n.panel h2{font-size:20px;font-weight:800;color:#f3dfae;text-align:center;}\n.panel .sub{font-size:13px;color:rgba(255,255,255,.6);text-align:center;margin:5px 0 20px;}\n.campo{margin-bottom:14px;}\n.campo label{\n  display:block;font-size:12px;font-weight:700;color:rgba(255,255,255,.55);\n  text-transform:uppercase;letter-spacing:.8px;margin-bottom:6px;\n}\n.campo input{\n  width:100%;padding:14px 16px;font-size:17px;font-family:inherit;font-weight:600;\n  border:2px solid rgba(255,255,255,.16);border-radius:14px;\n  background:rgba(255,255,255,.07);color:#fff;\n}\n.campo input:focus{outline:none;border-color:var(--oro);background:rgba(255,255,255,.12);}\n.campo input.codigo{\n  text-align:center;font-size:30px;letter-spacing:10px;font-weight:800;\n  text-transform:uppercase;padding:16px 10px 16px 20px;\n}\n.btn{\n  width:100%;padding:16px;font-size:17px;font-weight:800;font-family:inherit;\n  border:none;border-radius:15px;cursor:pointer;margin-top:10px;\n  background:linear-gradient(140deg,#177a45,#22a35b);color:#f7edd2;\n}\n.btn:active{transform:scale(.98);}\n.btn.gris{background:rgba(255,255,255,.12);color:#fff;}\n.btn.oro{background:linear-gradient(140deg,#c9a139,#e5c469);color:#3a2c08;}\n.btn:disabled{opacity:.45;}\n.aviso-error{\n  background:rgba(198,47,47,.3);border:1.5px solid #f08a8a;border-radius:12px;\n  padding:12px 14px;font-size:14px;margin-bottom:14px;color:#ffd9d9;\n}\n.separador{\n  display:flex;align-items:center;gap:12px;margin:20px 0 14px;\n  font-size:12px;color:rgba(255,255,255,.35);text-transform:uppercase;letter-spacing:1px;\n}\n.separador::before,.separador::after{content:\'\';flex:1;height:1px;background:rgba(255,255,255,.15);}\n\n/* ══ SALA DE ESPERA ══ */\n.codigo-mesa{\n  background:rgba(216,180,94,.14);border:2px dashed var(--oro);border-radius:16px;\n  padding:16px;text-align:center;margin-bottom:18px;\n}\n.codigo-mesa .etiqueta{font-size:12px;color:rgba(255,255,255,.6);text-transform:uppercase;letter-spacing:1px;}\n.codigo-mesa .valor{font-size:42px;font-weight:800;color:#f3dfae;letter-spacing:10px;margin:4px 0 2px;}\n.codigo-mesa .pista{font-size:12px;color:rgba(255,255,255,.5);}\n.lista-espera{margin-bottom:16px;}\n.silla{\n  display:flex;align-items:center;gap:12px;padding:13px 14px;\n  background:rgba(255,255,255,.06);border-radius:14px;margin-bottom:8px;\n}\n.silla.vacia{background:rgba(255,255,255,.03);border:1.5px dashed rgba(255,255,255,.15);}\n.silla .num{\n  width:32px;height:32px;border-radius:50%;flex-shrink:0;\n  display:flex;align-items:center;justify-content:center;\n  font-size:12px;font-weight:800;color:#fff;\n  border:2px solid rgba(255,255,255,.25);\n}\n.silla .quien{flex:1;font-size:16px;font-weight:700;}\n.silla .marca{font-size:12px;color:var(--oro);font-weight:700;}\n.silla.vacia .quien{color:rgba(255,255,255,.35);font-weight:500;}\n\n/* ══ MESA ══ */\n.esquina{position:absolute;top:calc(12px + env(safe-area-inset-top));left:12px;z-index:20;}\n.esquina{width:64px;}\n.sello-mano{\n  width:64px;height:64px;border-radius:15px;cursor:pointer;\n  display:flex;align-items:center;justify-content:center;position:relative;\n  border:2.5px solid var(--oro);\n  box-shadow:0 5px 18px rgba(0,0,0,.45),inset 0 2px 0 rgba(255,255,255,.22);\n}\n.sello-mano.neg{background:linear-gradient(150deg,#8f1d1d,#5f1212);}\n.sello-mano.pos{background:linear-gradient(150deg,#177a45,#0e5c33);}\n.sello-mano svg{width:54px;height:54px;}\n\n.marca-casa{\n  position:absolute;bottom:10px;left:12px;z-index:5;\n  font-size:10px;font-weight:800;letter-spacing:1.4px;\n  color:rgba(243,223,174,.55);text-transform:uppercase;\n  text-shadow:0 1px 3px rgba(0,0,0,.5);pointer-events:none;\n}\n/* Boton para repasar la baza anterior */\n.btn-ultima{\n  margin-top:7px;width:64px;height:34px;\n  border-radius:11px;cursor:pointer;\n  border:1.5px solid rgba(216,180,94,.4);\n  background:rgba(0,0,0,.38);color:#f3dfae;\n  font-size:16px;font-family:inherit;\n  display:flex;align-items:center;justify-content:center;\n}\n.btn-ultima:active{transform:scale(.94);}\n.btn-ultima:disabled{opacity:.3;}\n.baza-repaso{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:16px;}\n.baza-repaso .carta{width:100%;height:auto;aspect-ratio:5/7;--carta-mesa:62px;}\n.baza-repaso .carta .esq{font-size:11px;}\n.baza-item{text-align:center;}\n.baza-item .carta{margin:0 auto;width:100%;height:auto;aspect-ratio:5/7;}\n.baza-quien{font-size:12px;font-weight:700;color:rgba(255,255,255,.75);margin-bottom:5px;}\n.baza-sello{font-size:10px;font-weight:700;color:var(--oro);margin-top:5px;height:13px;}\n.baza-item.gano .carta{box-shadow:0 0 0 2.5px var(--oro),0 5px 14px rgba(0,0,0,.4);}\n/* Un halo alrededor de la mesa cuando te toca */\n.mesa{flex:1;position:relative;min-height:0;padding-top:env(safe-area-inset-top);}\n.mesa::before{\n  content:\'\';position:absolute;inset:0;pointer-events:none;z-index:1;\n  box-shadow:inset 0 0 90px rgba(0,0,0,.42);\n}\n/* Canto del tapete, apenas insinuado */\n.mesa::after{\n  content:\'\';position:absolute;pointer-events:none;z-index:0;\n  left:8%;right:8%;top:18%;bottom:10%;\n  border-radius:50%;\n  border:1px solid rgba(216,180,94,.09);\n  box-shadow:0 0 40px rgba(0,0,0,.14);\n}\n.puesto{position:absolute;display:flex;flex-direction:column;align-items:center;gap:5px;}\n.puesto,.tu-ficha{position:relative;}\n.puesto{position:absolute;}\n.puesto.norte{\n  top:calc(10px + env(safe-area-inset-top));left:50%;transform:translateX(-50%);\n}\n.puesto.norte .ficha{flex-direction:column;gap:5px;padding:8px 12px;border-radius:20px;}\n.puesto.norte .ficha-txt{text-align:center;}\n.puesto.norte .ficha-pts{font-size:10.5px;}\n.puesto.oeste{left:calc(6px + env(safe-area-inset-left));top:44%;transform:translateY(-50%);align-items:flex-start;max-width:38%;}\n.puesto.este{right:calc(6px + env(safe-area-inset-right));top:44%;transform:translateY(-50%);align-items:flex-end;max-width:38%;}\n.ficha{\n  display:flex;align-items:center;gap:8px;white-space:nowrap;\n  background:rgba(0,0,0,.34);border-radius:999px;padding:5px 12px 5px 5px;\n  border:1.5px solid transparent;transition:.2s;\n}\n@keyframes late{\n  0%,100%{box-shadow:0 0 0 0 rgba(216,180,94,.55),0 0 14px rgba(216,180,94,.3);}\n  55%{box-shadow:0 0 0 9px rgba(216,180,94,0),0 0 22px rgba(216,180,94,.5);}\n}\n.ficha.turno{\n  border-color:var(--oro);background:rgba(216,180,94,.28);\n  animation:late 1.5s ease-out infinite;\n}\n.ficha.turno .ficha.caido{opacity:.45;}\n.avatar{\n  width:34px;height:34px;border-radius:50%;flex-shrink:0;\n  display:flex;align-items:center;justify-content:center;\n  font-size:12.5px;font-weight:800;color:#fff;\n  border:2px solid rgba(255,255,255,.28);\n  box-shadow:0 2px 6px rgba(0,0,0,.35),inset 0 2px 4px rgba(255,255,255,.3);\n}\n.ficha-txt{line-height:1.15;}\n/* En los costados el nombre va en vertical, asi la ficha es estrecha\n   y no se come el sitio de las cartas */\n.puesto.oeste .ficha,.puesto.este .ficha{\n  flex-direction:column;gap:6px;padding:8px 5px;border-radius:22px;\n}\n.puesto.oeste .ficha-txt,.puesto.este .ficha-txt{\n  writing-mode:vertical-rl;text-orientation:mixed;\n  display:flex;align-items:center;gap:6px;\n}\n.puesto.este .ficha-txt{transform:rotate(180deg);}\n.puesto.oeste .ficha-pts,.puesto.este .ficha-pts{font-size:10.5px;}\n.ficha-pts{font-size:11.5px;color:rgba(255,255,255,.9);font-weight:800;}\n\n.centro{\n  position:absolute;top:calc(56% + env(safe-area-inset-top) / 2);left:50%;\n  transform:translate(-50%,-50%);\n  width:1px;height:1px;\n}\n.jugada{\n  position:absolute;top:0;left:0;\n  filter:drop-shadow(0 5px 12px rgba(0,0,0,.45));\n}\n/* Solo la carta recién soltada hace su entrada; las demás ya están puestas */\n.jugada.entrando{ animation:cae .26s cubic-bezier(.2,.8,.35,1) both; }\n@keyframes cae{ from{opacity:.35;} }\n/* Paso 1: las cuatro se cierran en un montón ordenado */\n.centro.juntando .jugada{\n  transition:transform .26s cubic-bezier(.35,0,.25,1)!important;\n  transform:translate(-50%,-50%) rotate(var(--giro-final,0deg))!important;\n}\n/* Paso 2: el montón entero se va hacia quien gana la baza */\n.centro{\n  transition:transform .42s cubic-bezier(.5,0,.72,.42),opacity .42s ease-in;\n}\n.centro.recoge-sur{transform:translate(-50%,-50%) translate(4px,230px) scale(.46);opacity:0;}\n.centro.recoge-norte{transform:translate(-50%,-50%) translate(-4px,-230px) scale(.46);opacity:0;}\n.centro.recoge-oeste{transform:translate(-50%,-50%) translate(-215px,10px) scale(.46);opacity:0;}\n.centro.recoge-este{transform:translate(-50%,-50%) translate(215px,-10px) scale(.46);opacity:0;}\n@keyframes destello{\n  35%{box-shadow:0 0 0 5px #ffe9a8,0 0 30px rgba(255,222,140,.9);}\n}\n.jugada.ganadora .carta{animation:destello .6s ease-out;box-shadow:0 0 0 3px var(--oro),0 8px 22px rgba(0,0,0,.45);}\n\n.marca-pts{\n  position:absolute;top:-14px;left:50%;transform:translateX(-50%);\n  font-size:15px;font-weight:800;padding:3px 10px;border-radius:999px;white-space:nowrap;\n  box-shadow:0 3px 10px rgba(0,0,0,.35);\n}\n.marca-pts.menos{background:#c62f2f;color:#fff;}\n.marca-pts.mas{background:#1c9c56;color:#fff;}\n\n/* ══ CARTAS ══ */\n.carta,.carta-mano{\n  background:\n    radial-gradient(ellipse at 30% 18%,rgba(255,255,255,.9),transparent 55%),\n    linear-gradient(168deg,#fff 0%,#fcfcfb 55%,#f4f5f2 100%);\n  border:1px solid rgba(20,25,30,.18);\n  position:relative;color:#111;font-weight:600;line-height:1;\n  display:flex;align-items:center;justify-content:center;overflow:hidden;\n}\n/* Filo claro que da grosor al canto */\n.carta::after,.carta-mano::after{\n  content:\'\';position:absolute;inset:0;border-radius:inherit;pointer-events:none;\n  box-shadow:inset 0 1px 0 rgba(255,255,255,.95),inset 0 -1px 0 rgba(0,0,0,.06);\n}\n.carta{width:var(--carta-mesa,110px);height:calc(var(--carta-mesa,110px) / 0.705);border-radius:12px;box-shadow:0 5px 13px rgba(0,0,0,.4);}\n.carta.roja,.carta-mano.roja{color:#d81f26;}\n.esq{\n  position:absolute;display:flex;flex-direction:column;align-items:center;\n  line-height:.86;z-index:2;\n}\n.esq.ai{top:5px;left:6px;}\n.esq.bd{bottom:5px;right:6px;transform:rotate(180deg);}\n.esq b{font-size:2.15em;letter-spacing:-1.5px;font-weight:800;line-height:.78;}\n.esq i{font-style:normal;font-size:1.25em;margin-top:2px;line-height:.9;}\n.carta:has(.figura) .esq i,.carta-mano:has(.figura) .esq i{font-size:1.5em;}\n.carta .esq{font-size:calc(var(--carta-mesa,110px) * 0.17);}\n.carta-mano .esq{font-size:15px;}\n.medallon{width:66%;height:72%;}\n.medallon.pips{width:52%;height:56%;}\n.medallon.as{width:56%;height:60%;}\n.medallon.figura{width:62%;height:70%;}\n.medallon.rey-casa{width:60%;height:68%;}\n\n.zona-mano{flex-shrink:0;position:relative;overflow:hidden;\n  padding:34px 6px calc(10px + env(safe-area-inset-bottom));}\n.zona-mano::before{\n  content:\'\';position:absolute;top:-8px;left:-14%;right:-14%;height:70px;\n  border-radius:50%;pointer-events:none;\n  border-top:2.5px solid rgba(216,180,94,.6);\n  box-shadow:0 -3px 16px rgba(0,0,0,.32);\n  background:linear-gradient(180deg,transparent 46%,rgba(6,40,22,.5));\n}\n.mano{display:flex;flex-direction:column;align-items:center;gap:4px;padding:0 4px 2px;\n  --ancho:74px;--alto:105px;--solape:-34px;}\n.mano.dos-filas{gap:0;}\n.mano.dos-filas .fila:last-child{margin-top:calc(var(--alto) * -0.38);z-index:3;}\n.fila{display:flex;justify-content:center;align-items:flex-start;max-width:100%;}\n.carta-mano{\n  width:var(--ancho);height:var(--alto);border-radius:10px;\n  box-shadow:0 4px 11px rgba(0,0,0,.34);margin-left:var(--solape);flex-shrink:0;\n  transition:margin-left .24s ease,transform .18s ease,opacity .18s,box-shadow .18s;\n}\n.fila .carta-mano:first-child{margin-left:0;}\n.carta-mano.nuevo-palo{margin-left:calc(var(--solape) + 8px);}\n.fila .carta-mano.nuevo-palo:first-child{margin-left:0;}\n.carta-mano.jugable{\n  box-shadow:0 7px 16px rgba(0,0,0,.4),0 0 0 2px rgba(52,196,111,.9);\n  cursor:pointer;\n}\n.mano .carta-mano.jugable{margin-top:-6px;}\n/* La carta elegida se levanta a la espera de confirmación */\n.carta-mano.elegida{\n  transform:translateY(-22px) scale(1.04)!important;\n  box-shadow:0 12px 26px rgba(0,0,0,.5),0 0 0 3px var(--oro)!important;\n  z-index:10;\n}\n.carta-mano.jugable:active{transform:translateY(-18px) scale(1.05)!important;z-index:9;}\n.carta-mano.vetada{opacity:.62;}\n.tu-ficha{display:flex;align-items:center;justify-content:center;gap:8px;margin-top:8px;position:relative;}\n\n/* ══ MENSAJES ══ */\n.puntos-mano{\n  position:absolute;left:50%;top:-18px;\n  padding:7px 16px;border-radius:999px;\n  font-size:21px;font-weight:800;white-space:nowrap;z-index:45;\n  border:2px solid rgba(255,255,255,.55);\n  box-shadow:0 5px 18px rgba(0,0,0,.45);\n  animation:brota 1.9s ease-out both;\n}\n@keyframes brota{\n  0%{opacity:0;transform:translate(-50%,10px) scale(.7);}\n  20%{opacity:1;transform:translate(-50%,-4px) scale(1.06);}\n  30%{transform:translate(-50%,0) scale(1);}\n  82%{opacity:1;transform:translate(-50%,0) scale(1);}\n  100%{opacity:0;transform:translate(-50%,-14px) scale(.95);}\n}\n.puntos-mano.suma{background:linear-gradient(165deg,#5fd07a,#218b45);color:#fff;}\n.puntos-mano.resta{background:linear-gradient(165deg,#e8544c,#a81d1d);color:#fff;}\n.puntos-mano.cero{background:linear-gradient(165deg,#eef1f3,#c9d0d6);color:#26313c;}\n\n.burla{\n  position:fixed;inset:0;z-index:300;pointer-events:none;overflow:hidden;\n  background:radial-gradient(circle at 50% 42%,rgba(0,0,0,.45),rgba(0,0,0,.7));\n  animation:burla-fondo 2.6s ease-out both;\n}\n@keyframes burla-fondo{ 0%{opacity:0;} 12%{opacity:1;} 82%{opacity:1;} 100%{opacity:0;} }\n.burla-carta{\n  position:absolute;top:34%;left:50%;\n  animation:burla-cae 2.6s cubic-bezier(.2,1.5,.4,1) both;\n}\n@keyframes burla-cae{\n  0%{transform:translate(-50%,-260%) rotate(-30deg) scale(.5);opacity:0;}\n  18%{transform:translate(-50%,-50%) rotate(0) scale(1.25);opacity:1;}\n  24%{transform:translate(-50%,-46%) rotate(-7deg) scale(1.15);}\n  30%{transform:translate(-50%,-50%) rotate(7deg) scale(1.2);}\n  36%{transform:translate(-50%,-48%) rotate(-5deg) scale(1.18);}\n  42%,84%{transform:translate(-50%,-50%) rotate(0) scale(1.18);opacity:1;}\n  100%{transform:translate(-50%,-58%) rotate(3deg) scale(1.1);opacity:0;}\n}\n.burla-carta .carta{box-shadow:0 12px 40px rgba(0,0,0,.6),0 0 0 4px rgba(216,180,94,.9);}\n.burla-texto{\n  position:absolute;top:66%;left:50%;transform:translateX(-50%);\n  text-align:center;white-space:nowrap;\n  font-size:24px;font-weight:800;color:#f7e6b8;\n  text-shadow:0 3px 12px rgba(0,0,0,.8);\n  animation:burla-texto 2.6s ease-out both;\n}\n.burla-texto span{\n  display:block;font-size:34px;color:#ff6b6b;margin-top:4px;\n}\n@keyframes burla-texto{\n  0%,20%{opacity:0;transform:translateX(-50%) scale(.7);}\n  32%{opacity:1;transform:translateX(-50%) scale(1.12);}\n  40%,86%{opacity:1;transform:translateX(-50%) scale(1);}\n  100%{opacity:0;}\n}\n.risa{\n  position:absolute;bottom:-10%;\n  animation:sube 2.4s ease-out both;\n}\n@keyframes sube{\n  0%{transform:translateY(0) rotate(0);opacity:0;}\n  15%{opacity:1;}\n  100%{transform:translateY(-115vh) rotate(320deg);opacity:0;}\n}\n.btn-sonido{\n  margin-top:7px;width:64px;height:34px;border-radius:11px;cursor:pointer;\n  border:1.5px solid rgba(216,180,94,.4);\n  background:rgba(0,0,0,.38);color:#f3dfae;font-size:15px;font-family:inherit;\n  display:flex;align-items:center;justify-content:center;\n}\n\n.paleta{\n  position:fixed;left:8px;right:8px;z-index:60;\n  display:grid;grid-template-columns:repeat(4,1fr);gap:7px;\n  background:rgba(6,32,18,.95);border:1.5px solid rgba(216,180,94,.45);\n  border-radius:18px;padding:10px;\n  box-shadow:0 10px 30px rgba(0,0,0,.5);\n}\n.decir{\n  display:flex;flex-direction:column;align-items:center;gap:3px;\n  padding:8px 2px;border-radius:12px;cursor:pointer;font-family:inherit;\n  border:1.5px solid rgba(255,255,255,.1);background:rgba(255,255,255,.06);\n}\n.decir:active{transform:scale(.93);background:rgba(216,180,94,.2);}\n.decir-e{font-size:23px;line-height:1;}\n.decir-t{font-size:9.5px;font-weight:700;color:rgba(255,255,255,.7);text-align:center;line-height:1.1;}\n\n/* El globo aparece pegado a la ficha de quien habla */\n.capa-globos{position:fixed;inset:0;z-index:70;pointer-events:none;}\n.globo{\n  position:fixed;white-space:nowrap;pointer-events:none;\n  background:#fff;color:#16202c;border-radius:14px;\n  padding:6px 11px;font-size:12.5px;font-weight:700;\n  box-shadow:0 5px 16px rgba(0,0,0,.4);\n  animation:globo-sale 2.6s ease-out both;\n}\n.globo b{font-size:16px;margin-right:5px;}\n.globo::after{\n  content:\'\';position:absolute;width:9px;height:9px;background:#fff;\n  transform:rotate(45deg);\n}\n.globo.norte::after{top:-4px;left:calc(50% - 4px);}\n.globo.sur::after{bottom:-4px;left:calc(50% - 4px);}\n.globo.oeste::after{left:-4px;top:calc(50% - 4px);}\n.globo.este::after{right:-4px;top:calc(50% - 4px);}\n@keyframes globo-sale{\n  0%{opacity:0;transform:scale(.6);}\n  12%{opacity:1;transform:scale(1.06);}\n  20%,86%{opacity:1;transform:scale(1);}\n  100%{opacity:0;transform:scale(.95);}\n}\n.palos-elegir{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:16px 0;}\n.palo-op{\n  padding:18px 6px;border-radius:14px;border:2px solid rgba(255,255,255,.16);\n  background:rgba(255,255,255,.07);cursor:pointer;text-align:center;font-family:inherit;\n}\n.palo-op b{display:block;font-size:32px;line-height:1;color:#fff;}\n.palo-op.roja b{color:#ff8080;}\n.palo-op span{display:block;font-size:11px;color:rgba(255,255,255,.6);margin-top:6px;}\n.palo-op.mejor{border-color:var(--oro);background:rgba(216,180,94,.16);}\n\n.corona{font-size:56px;text-align:center;line-height:1;margin-bottom:6px;}\n.tabla tr.campeon td{color:#f7e6b8;font-weight:800;font-size:17px;}\n.silla.vacante{border-style:dashed;border-color:rgba(216,180,94,.5);}\n.silla.vacante .quien{color:rgba(243,223,174,.7);font-style:italic;}\n.mano-actual-info{\n  background:rgba(216,180,94,.13);border:1.5px solid rgba(216,180,94,.4);\n  border-radius:14px;padding:12px 14px;margin-bottom:16px;text-align:center;\n}\n.mano-nombre{font-size:17px;font-weight:800;color:#f3dfae;}\n.mano-explica{font-size:13px;color:rgba(255,255,255,.7);margin-top:3px;}\n.tabla{width:100%;border-collapse:collapse;font-size:15px;margin-bottom:16px;}\n.tabla td{padding:11px 10px;border-top:1px solid rgba(255,255,255,.1);}\n.tabla td:last-child{text-align:right;font-weight:800;}\n.tabla tr:first-child td{border-top:none;}\n.pos{color:#4ade80;} .neg{color:#f87171;}\n.botones-ronda{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:16px;}\n.btn-ronda{\n  padding:11px 4px;border-radius:13px;font-family:inherit;cursor:pointer;\n  border:2px solid rgba(255,255,255,.14);background:rgba(255,255,255,.06);\n  color:rgba(255,255,255,.55);font-size:16px;font-weight:800;line-height:1.2;\n}\n.btn-ronda span{display:block;font-size:9.5px;font-weight:600;margin-top:2px;opacity:.75;}\n.btn-ronda.jugada{\n  border-color:rgba(216,180,94,.6);background:rgba(216,180,94,.16);color:#f3dfae;\n}\n.btn-ronda.actual{\n  border-color:#4ade80;background:rgba(52,196,111,.18);color:#c6f6d5;\n}\n.btn-ronda:disabled{opacity:.35;cursor:default;}\n.despertando{\n  position:fixed;inset:0;z-index:400;\n  background:rgba(6,32,18,.94);\n  display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;\n  text-align:center;padding:24px;\n}\n.despertando p{font-size:17px;font-weight:800;color:#f3dfae;}\n.despertando span{font-size:13px;color:rgba(255,255,255,.6);max-width:260px;}\n.giro{\n  width:44px;height:44px;border-radius:50%;\n  border:3px solid rgba(216,180,94,.25);border-top-color:var(--oro);\n  animation:girar .9s linear infinite;\n}\n@keyframes girar{to{transform:rotate(360deg);}}\n.estado-red{\n  position:fixed;top:0;left:0;right:0;z-index:300;\n  background:#b3202a;color:#fff;text-align:center;\n  padding:9px;font-size:13px;font-weight:700;\n}\n\n/* En pantalla de escritorio las cartas se ven mas grandes */\n@media(max-width:400px){\n\n  .panel{padding:22px 18px;}\n  .campo input.codigo{font-size:26px;letter-spacing:8px;}\n}\n</style>\n</head>\n<body>\n\n<div class="estado-red oculto" id="estado-red">Reconectando…</div>\n<div class="despertando oculto" id="despertando">\n  <div class="giro"></div>\n  <p>Despertando el servidor…</p>\n  <span>La primera conexión del día tarda unos segundos</span>\n</div>\n\n<!-- ══ ENTRADA ══ -->\n<div class="portada" id="portada">\n  <div class="panel">\n    <div class="franja-logo"><img src="/cara.png" alt=""></div>\n    <div class="palos-marca">&#9824;<span class="r">&#9829;</span>&#9827;<span class="r">&#9830;</span></div>\n    <h1>KING CC</h1>\n    <p class="sub">Cuatro jugadores, cada uno en su teléfono</p>\n\n    <div id="error-entrada"></div>\n\n    <div class="campo">\n      <label>Tu nombre</label>\n      <input type="text" id="mi-nombre" maxlength="12" placeholder="¿Cómo te llamas?">\n    </div>\n\n    <button class="btn" onclick="crearMesa()">Crear una mesa</button>\n\n    <div class="separador">o entra a una</div>\n\n    <div class="campo">\n      <label>Código de la mesa</label>\n      <input type="text" id="codigo-entrada" class="codigo" maxlength="4" placeholder="CUCA"\n             autocapitalize="characters" autocomplete="off">\n    </div>\n    <button class="btn gris" onclick="entrarMesa()">Entrar</button>\n  </div>\n</div>\n\n<!-- ══ SALA DE ESPERA ══ -->\n<div class="portada oculto" id="espera">\n  <div class="panel">\n    <h2>Mesa lista</h2>\n    <p class="sub">Comparte el código con los demás</p>\n\n    <div class="codigo-mesa">\n      <div class="etiqueta">Código</div>\n      <div class="valor" id="codigo-mesa">····</div>\n      <div class="pista">Toca para copiarlo</div>\n    </div>\n\n    <div class="lista-espera" id="lista-espera"></div>\n\n    <button class="btn oculto" id="btn-empezar" onclick="empezar()">Empezar la partida</button>\n    <p class="sub oculto" id="aviso-espera">Esperando a que el anfitrión empiece…</p>\n  </div>\n</div>\n\n<!-- ══ MESA DE JUEGO ══ -->\n<div class="esquina oculto" id="esquina">\n  <div class="sello-mano neg" id="sello" onclick="verMarcador()"></div>\n  <button class="btn-ultima" onclick="verUltimaBaza()"\n          title="Ver la última baza">&#8634;</button>\n  <button class="btn-sonido" id="btn-sonido" onclick="alternarSonido()"\n          title="Sonido">&#128266;</button>\n  <button class="btn-sonido" id="btn-decir" onclick="alternarPaleta()"\n          title="Decir algo">&#128512;</button>\n</div>\n\n<div class="mesa oculto" id="mesa">\n  <div class="puesto norte" id="puesto-norte"></div>\n  <div class="puesto oeste" id="puesto-oeste"></div>\n  <div class="puesto este" id="puesto-este"></div>\n  <div class="centro" id="centro"></div>\n  <div class="marca-casa">KING CUCASTRO</div>\n</div>\n\n<div class="capa-globos" id="capa-globos"></div>\n<div class="paleta oculto" id="paleta"></div>\n\n<div class="zona-mano oculto" id="zona-mano">\n  <div class="mano" id="mi-mano"></div>\n  <div class="tu-ficha" id="tu-ficha"></div>\n</div>\n\n<script>\n\'use strict\';\n\n/* ═════ IDENTIDAD ═════ */\nvar MI_ID = localStorage.getItem(\'king_id\');\nif (!MI_ID) {\n  MI_ID = \'j\' + Date.now() + Math.random().toString(36).slice(2, 8);\n  try { localStorage.setItem(\'king_id\', MI_ID); } catch (e) {}\n}\n\nvar PALOS = [\'\\u2660\',\'\\u2665\',\'\\u2663\',\'\\u2666\'];\nvar COLORES = [\'#0ea5e9\',\'#ec4899\',\'#7c3aed\',\'#15a35b\'];\nvar PUESTOS = [\'sur\',\'oeste\',\'norte\',\'este\'];\n\nvar ws = null, estado = null, miSitio = -1, codigoActual = null;\nvar ultimaMesaVista = 0;\n\nfunction $(id){ return document.getElementById(id); }\nfunction esRoja(p){ return p === \'\\u2665\' || p === \'\\u2666\'; }\n\n/* ═════ CONEXIÓN ═════ */\nfunction conectar(alAbrir){\n  var protocolo = location.protocol === \'https:\' ? \'wss://\' : \'ws://\';\n  ws = new WebSocket(protocolo + location.host);\n\n  // Si tarda, es que el servidor estaba dormido: se avisa para que no parezca colgado\n  var avisoLento = setTimeout(function(){\n    $(\'despertando\').classList.remove(\'oculto\');\n  }, 1800);\n\n  ws.onopen = function(){\n    clearTimeout(avisoLento);\n    $(\'despertando\').classList.add(\'oculto\');\n    $(\'estado-red\').classList.add(\'oculto\');\n    if (alAbrir) alAbrir();\n  };\n\n  ws.onmessage = function(ev){\n    var m = JSON.parse(ev.data);\n\n    if (m.tipo === \'error\'){\n      mostrarError(m.texto);\n      return;\n    }\n    if (m.tipo === \'sala\'){\n      codigoActual = m.codigo;\n      miSitio = m.yo;\n      try { localStorage.setItem(\'king_mesa\', m.codigo); } catch(e){}\n      return;\n    }\n    if (m.tipo === \'estado\'){\n      estado = m.estado;\n      miSitio = estado.yo;\n      pintar();\n      return;\n    }\n    if (m.tipo === \'reaccion\'){\n      mostrarDecir(m.sitio, m.cual);\n      return;\n    }\n    if (m.tipo === \'finMano\'){\n      mostrarPuntosMano(m.puntos);\n      return;\n    }\n    if (m.tipo === \'esperandoJugador\'){\n      capa(\n        \'<h2>Falta un jugador</h2>\'+\n        \'<p class="sub">El sitio de <b>\'+m.nombre+\'</b> está libre y le toca jugar.<br>\'+\n        \'Que alguien entre con el código <b>\'+estado.codigo+\'</b> para ocuparlo.</p>\'+\n        \'<button class="btn" onclick="quitarCapa()">Entendido</button>\'\n      );\n      return;\n    }\n    if (m.tipo === \'finPartida\'){\n      mostrarFinPartida(m.marcador, m.rondas);\n      return;\n    }\n    if (m.tipo === \'finRonda\'){\n      mostrarFinRonda(m.marcador);\n      return;\n    }\n  };\n\n  ws.onclose = function(){\n    clearTimeout(avisoLento);\n    $(\'despertando\').classList.add(\'oculto\');\n    $(\'estado-red\').classList.remove(\'oculto\');\n    // Vuelve a entrar sola a la misma mesa\n    setTimeout(function(){\n      conectar(function(){\n        if (codigoActual) {\n          enviar({ tipo:\'entrar\', codigo: codigoActual, id: MI_ID, nombre: miNombre() });\n        }\n      });\n    }, 2000);\n  };\n}\n\nfunction enviar(obj){\n  if (ws && ws.readyState === 1) ws.send(JSON.stringify(obj));\n}\n\nfunction miNombre(){\n  var v = ($(\'mi-nombre\').value || \'\').trim();\n  if (!v) v = localStorage.getItem(\'king_nombre\') || \'\';\n  return v || \'Jugador\';\n}\n\nfunction mostrarError(texto){\n  $(\'error-entrada\').innerHTML = \'<div class="aviso-error">\' + texto + \'</div>\';\n  setTimeout(function(){ $(\'error-entrada\').innerHTML = \'\'; }, 4000);\n}\n\n/* ═════ ENTRAR ═════ */\nfunction crearMesa(){\n  var n = ($(\'mi-nombre\').value || \'\').trim();\n  if (!n) { mostrarError(\'Escribe tu nombre antes de crear la mesa\'); return; }\n  try { localStorage.setItem(\'king_nombre\', n); } catch(e){}\n  conectar(function(){\n    enviar({ tipo:\'crear\', id: MI_ID, nombre: n });\n  });\n}\n\nfunction entrarMesa(){\n  var n = ($(\'mi-nombre\').value || \'\').trim();\n  var c = ($(\'codigo-entrada\').value || \'\').trim().toUpperCase();\n  if (!n) { mostrarError(\'Escribe tu nombre\'); return; }\n  if (c.length !== 4) { mostrarError(\'El código tiene cuatro letras\'); return; }\n  try { localStorage.setItem(\'king_nombre\', n); } catch(e){}\n  codigoActual = c;\n  conectar(function(){\n    enviar({ tipo:\'entrar\', codigo: c, id: MI_ID, nombre: n });\n  });\n}\n\nfunction empezar(){ enviar({ tipo:\'empezar\' }); }\n\n/* Recordar el nombre de la vez anterior */\n(function(){\n  var n = localStorage.getItem(\'king_nombre\');\n  if (n) $(\'mi-nombre\').value = n;\n  $(\'codigo-entrada\').addEventListener(\'input\', function(){\n    this.value = this.value.toUpperCase().replace(/[^A-Z0-9]/g,\'\');\n  });\n  $(\'codigo-mesa\').addEventListener(\'click\', function(){\n    if (navigator.clipboard) navigator.clipboard.writeText(codigoActual || \'\');\n    var p = document.querySelector(\'.codigo-mesa .pista\');\n    p.textContent = \'Copiado\';\n    setTimeout(function(){ p.textContent = \'Toca para copiarlo\'; }, 1500);\n  });\n})();\n\n/* ═════ SONIDO ═════\n   Todo se genera en el momento, sin archivos: la app sigue siendo un solo fichero. */\nvar audio = null, silencio = false;\ntry { silencio = localStorage.getItem(\'king_silencio\') === \'1\'; } catch(e){}\n\nfunction despertarAudio(){\n  try {\n    if (!audio) audio = new (window.AudioContext || window.webkitAudioContext)();\n    if (audio.state === \'suspended\') audio.resume();\n  } catch(e){ audio = null; }\n}\ndocument.addEventListener(\'touchstart\', despertarAudio, { once:false });\ndocument.addEventListener(\'click\', despertarAudio, { once:false });\n\n// Golpe seco de carta: ruido corto y filtrado\nfunction ruidoCarta(){\n  if (silencio || !audio) return;\n  try {\n    var dur = 0.14, n = Math.floor(audio.sampleRate * dur);\n    var buf = audio.createBuffer(1, n, audio.sampleRate);\n    var d = buf.getChannelData(0);\n    for (var i = 0; i < n; i++){\n      var caida = Math.pow(1 - i/n, 4);\n      d[i] = (Math.random()*2 - 1) * caida;\n    }\n    var f = audio.createBufferSource(); f.buffer = buf;\n    var filtro = audio.createBiquadFilter();\n    filtro.type = \'bandpass\'; filtro.frequency.value = 2100; filtro.Q.value = 0.8;\n    var vol = audio.createGain(); vol.gain.value = 0.35;\n    f.connect(filtro); filtro.connect(vol); vol.connect(audio.destination);\n    f.start();\n  } catch(e){}\n}\n\n// Barrido al recoger la baza: ruido más largo que se apaga\nfunction ruidoRecoger(){\n  if (silencio || !audio) return;\n  try {\n    var dur = 0.42, n = Math.floor(audio.sampleRate * dur);\n    var buf = audio.createBuffer(1, n, audio.sampleRate);\n    var d = buf.getChannelData(0);\n    for (var i = 0; i < n; i++){\n      var t = i/n;\n      d[i] = (Math.random()*2 - 1) * Math.sin(Math.PI*t) * (1 - t*0.5);\n    }\n    var f = audio.createBufferSource(); f.buffer = buf;\n    var filtro = audio.createBiquadFilter();\n    filtro.type = \'lowpass\';\n    filtro.frequency.setValueAtTime(3200, audio.currentTime);\n    filtro.frequency.exponentialRampToValueAtTime(700, audio.currentTime + dur);\n    var vol = audio.createGain(); vol.gain.value = 0.28;\n    f.connect(filtro); filtro.connect(vol); vol.connect(audio.destination);\n    f.start();\n  } catch(e){}\n}\n\n// Trombón de burla: cuatro notas que van cayendo\nfunction ruidoBurla(){\n  if (silencio || !audio) return;\n  try {\n    var notas = [392, 349.2, 311.1, 261.6];   // sol, fa, mi bemol, do\n    notas.forEach(function(hz, k){\n      var t0 = audio.currentTime + k * 0.26;\n      var osc = audio.createOscillator();\n      osc.type = \'sawtooth\';\n      osc.frequency.setValueAtTime(hz, t0);\n      osc.frequency.linearRampToValueAtTime(hz * 0.86, t0 + 0.24);\n      var filtro = audio.createBiquadFilter();\n      filtro.type = \'lowpass\'; filtro.frequency.value = 1300;\n      var vol = audio.createGain();\n      vol.gain.setValueAtTime(0.0001, t0);\n      vol.gain.exponentialRampToValueAtTime(0.22, t0 + 0.04);\n      vol.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.25);\n      osc.connect(filtro); filtro.connect(vol); vol.connect(audio.destination);\n      osc.start(t0); osc.stop(t0 + 0.27);\n    });\n  } catch(e){}\n}\n\nfunction alternarSonido(){\n  silencio = !silencio;\n  try { localStorage.setItem(\'king_silencio\', silencio ? \'1\' : \'0\'); } catch(e){}\n  var b = $(\'btn-sonido\');\n  if (b) b.textContent = silencio ? \'\\u{1F507}\' : \'\\u{1F50A}\';\n  if (!silencio) { despertarAudio(); ruidoCarta(); }\n}\n\n/* La burla: el rey de corazones cae encima de quien se lo lleva */\nfunction mostrarBurla(nombre, esMio){\n  var caras = \'\';\n  for (var i = 0; i < 9; i++){\n    caras += \'<span class="risa" style="left:\'+(6 + i*11)+\'%;\'+\n      \'animation-delay:\'+(i*0.13).toFixed(2)+\'s;\'+\n      \'font-size:\'+(26 + (i%3)*10)+\'px">\\u{1F602}</span>\';\n  }\n  var capa = document.createElement(\'div\');\n  capa.className = \'burla\';\n  capa.innerHTML =\n    \'<div class="burla-carta">\'+htmlCarta({p:\'\\u2665\',v:\'K\'},\'carta\')+\'</div>\'+\n    \'<div class="burla-texto">\'+(esMio ? \'\\u00a1Te lo comiste!\' : \'\\u00a1\'+nombre+\' se lo comi\\u00f3!\')+\n      \'<span>\\u2212160</span></div>\'+\n    caras;\n  document.body.appendChild(capa);\n  ruidoBurla();\n  setTimeout(function(){ if (capa.parentNode) capa.parentNode.removeChild(capa); }, 2600);\n}\n\n/* ═════ REACCIONES RÁPIDAS ═════\n   Un toque, sin teclado: el teclado taparía la mesa entera. */\nvar DECIRES = [\n  { e:\'\\u{1F44F}\', t:\'\\u00a1Buena!\' },\n  { e:\'\\u{1F602}\', t:\'\\u00a1Ja!\' },\n  { e:\'\\u{1F631}\', t:\'\\u00a1Uy\\u2026!\' },\n  { e:\'\\u{1F60F}\', t:\'Ya ver\\u00e1s\' },\n  { e:\'\\u{1F64F}\', t:\'No me la eches\' },\n  { e:\'\\u{1F480}\', t:\'Me mataste\' },\n  { e:\'\\u{1F914}\', t:\'D\\u00e9jame pensar\' },\n  { e:\'\\u{1F525}\', t:\'\\u00a1Qu\\u00e9 mano!\' },\n  { e:\'\\u{1F62D}\', t:\'Otra vez no\' },\n  { e:\'\\u{1F91D}\', t:\'Bien jugado\' },\n  { e:\'\\u{1F40C}\', t:\'\\u00a1Corre!\' },\n  { e:\'\\u{1F44B}\', t:\'Ahora vuelvo\' }\n];\n\nfunction alternarPaleta(){\n  var pal = $(\'paleta\');\n  if (!pal.classList.contains(\'oculto\')){ pal.classList.add(\'oculto\'); return; }\n  pal.innerHTML = DECIRES.map(function(d, i){\n    return \'<button class="decir" onclick="decir(\'+i+\')">\'+\n      \'<span class="decir-e">\'+d.e+\'</span>\'+\n      \'<span class="decir-t">\'+d.t+\'</span></button>\';\n  }).join(\'\');\n  // Se coloca justo encima de la mano, sea cual sea su alto\n  var zona = $(\'zona-mano\');\n  var alto = zona ? zona.getBoundingClientRect().height : 280;\n  pal.style.bottom = Math.round(alto + 10) + \'px\';\n  pal.classList.remove(\'oculto\');\n}\n\nfunction decir(i){\n  $(\'paleta\').classList.add(\'oculto\');\n  enviar({ tipo:\'reaccion\', cual:i });\n}\n\n/* El globo sale junto a la ficha de quien lo manda y se va solo.\n   Va en su propia capa: si fuera dentro de la ficha, lo borraría\n   el repintado que ocurre con cada carta jugada. */\nfunction mostrarDecir(sitio, cual){\n  var d = DECIRES[cual] || DECIRES[0];\n  var ancla = (sitio === miSitio) ? $(\'tu-ficha\') : $(\'puesto-\' + puestoDe(sitio));\n  var capa = $(\'capa-globos\');\n  if (!ancla || !capa) return;\n\n  // Uno por jugador: el nuevo sustituye al anterior\n  var previo = capa.querySelector(\'[data-sitio="\' + sitio + \'"]\');\n  if (previo) previo.parentNode.removeChild(previo);\n\n  var r = ancla.getBoundingClientRect();\n  var donde = (sitio === miSitio) ? \'sur\' : puestoDe(sitio);\n  var g = document.createElement(\'div\');\n  g.className = \'globo \' + donde;\n  g.setAttribute(\'data-sitio\', sitio);\n  g.innerHTML = \'<b>\' + d.e + \'</b>\' + d.t;\n  capa.appendChild(g);\n\n  // Se coloca al lado que corresponda, sin salirse de la pantalla\n  var an = g.offsetWidth, al = g.offsetHeight, m = 8;\n  var x, y;\n  if (donde === \'norte\'){ x = r.left + r.width/2 - an/2; y = r.bottom + 9; }\n  else if (donde === \'sur\'){ x = r.left + r.width/2 - an/2; y = r.top - al - 9; }\n  else if (donde === \'oeste\'){ x = r.right + 9; y = r.top + 6; }\n  else { x = r.left - an - 9; y = r.top + 6; }\n  x = Math.max(m, Math.min(x, window.innerWidth - an - m));\n  y = Math.max(m, Math.min(y, window.innerHeight - al - m));\n  g.style.left = Math.round(x) + \'px\';\n  g.style.top  = Math.round(y) + \'px\';\n\n  setTimeout(function(){ if (g.parentNode) g.parentNode.removeChild(g); }, 2600);\n}\n\n/* ═════ CARTAS ═════ */\n/* Corona de rayos finos alrededor del palo, como en las barajas clásicas */\nfunction rayos(col){\n  var s = \'\';\n  for (var a = 0; a < 48; a++){\n    var r = a * 7.5 * Math.PI / 180;\n    var x1 = 50 + Math.cos(r) * 33, y1 = 50 + Math.sin(r) * 33;\n    var x2 = 50 + Math.cos(r) * 45, y2 = 50 + Math.sin(r) * 45;\n    s += \'<line x1="\'+x1.toFixed(1)+\'" y1="\'+y1.toFixed(1)+\'" x2="\'+x2.toFixed(1)+\n         \'" y2="\'+y2.toFixed(1)+\'" stroke="\'+col+\'" stroke-width="2.8" stroke-linecap="round"/>\';\n  }\n  return s;\n}\nfunction simbolos(valor, palo, col){\n  // El palo, sin adornos, en el centro de la carta\n  return \'<text x="50" y="52" font-size="62" fill="\'+col+\'" text-anchor="middle" \'+\n    \'dominant-baseline="central">\'+palo+\'</text>\';\n}\nfunction asGrande(palo, col){\n  return \'<text x="50" y="52" font-size="78" fill="\'+col+\'" text-anchor="middle" \'+\n    \'dominant-baseline="central">\'+palo+\'</text>\';\n}\n// Cada palo con su juego de colores planos, como en las barajas modernas\nvar PALETA = {\n  \'\\u2660\': { fuerte:\'#1c1c1c\', suave:\'#2f6ea8\', claro:\'#c6ced5\', piel:\'#f6e3cd\', oro:\'#e8b93a\' },\n  \'\\u2665\': { fuerte:\'#d81f26\', suave:\'#1c1c1c\', claro:\'#f2d3c4\', piel:\'#f6e3cd\', oro:\'#e8b93a\' },\n  \'\\u2663\': { fuerte:\'#1f5c33\', suave:\'#1c1c1c\', claro:\'#cfdfd3\', piel:\'#f6e3cd\', oro:\'#e8b93a\' },\n  \'\\u2666\': { fuerte:\'#e07a1f\', suave:\'#1f6f6b\', claro:\'#f7e0c4\', piel:\'#f6e3cd\', oro:\'#e8b93a\' }\n};\nfunction medioRetrato(valor, palo, col, rojo){\n  var P = PALETA[palo] || PALETA[\'\\u2660\'];\n  var T = \'#1c1c1c\';\n  var g = \'\';\n\n  // ── Cuerpo: hombros anchos que llegan casi al borde\n  g += \'<path d="M8 50 L14 30 Q50 21 86 30 L92 50 Z" fill="\'+P.fuerte+\'" stroke="\'+T+\'" stroke-width="1"/>\';\n  // Mitad izquierda en el color secundario\n  g += \'<path d="M8 50 L14 30 Q32 25 50 24 L50 50 Z" fill="\'+P.suave+\'"/>\';\n  // Franjas diagonales sobre el pecho\n  g += \'<path d="M26 50 L40 26 L48 26 L34 50 Z" fill="\'+P.claro+\'"/>\';\n  g += \'<path d="M52 50 L66 26 L74 26 L60 50 Z" fill="\'+P.claro+\'"/>\';\n  // Rombos sobre las franjas\n  g += \'<g fill="\'+P.fuerte+\'">\';\n  [[33,34],[30,42],[63,34],[60,42]].forEach(function(pt){\n    g += \'<path d="M\'+pt[0]+\' \'+(pt[1]-3)+\' l3 3 -3 3 -3 -3 Z"/>\';\n  });\n  g += \'</g>\';\n  // Contorno y filo dorado\n  g += \'<path d="M8 50 L14 30 Q50 21 86 30 L92 50" fill="none" stroke="\'+T+\'" stroke-width="1.2"/>\';\n  g += \'<path d="M12 50 L17.5 32 Q50 24 82.5 32 L88 50" fill="none" stroke="\'+P.oro+\'" stroke-width="1.6"/>\';\n\n  // ── Cuello\n  g += \'<path d="M42 24 L42 30 L58 30 L58 24 Z" fill="\'+P.piel+\'" stroke="\'+T+\'" stroke-width="1"/>\';\n\n  // ── Cabeza, bien visible\n  g += \'<rect x="37" y="4" width="26" height="22" rx="6" fill="\'+P.piel+\'" stroke="\'+T+\'" stroke-width="1.2"/>\';\n  g += \'<circle cx="44.5" cy="14" r="1.7" fill="\'+T+\'"/>\';\n  g += \'<circle cx="55.5" cy="14" r="1.7" fill="\'+T+\'"/>\';\n  g += \'<path d="M50 14 L50 19" stroke="\'+T+\'" stroke-width="1.2"/>\';\n\n  if (valor === \'K\'){\n    // Melena y barba\n    g += \'<path d="M31 8 L37 8 L37 27 L31 27 Z" fill="\'+P.oro+\'" stroke="\'+T+\'" stroke-width="1"/>\';\n    g += \'<path d="M63 8 L69 8 L69 27 L63 27 Z" fill="\'+P.oro+\'" stroke="\'+T+\'" stroke-width="1"/>\';\n    g += \'<path d="M40 21 L60 21 L55 30 L45 30 Z" fill="\'+P.oro+\'" stroke="\'+T+\'" stroke-width="1"/>\';\n    // Corona de tres puntas\n    g += \'<path d="M33 6 L35 -3 L42 3 L50 -5 L58 3 L65 -3 L67 6 Z" fill="\'+P.oro+\'" stroke="\'+T+\'" stroke-width="1.2"/>\';\n    g += \'<rect x="33" y="5" width="34" height="4.5" fill="\'+P.oro+\'" stroke="\'+T+\'" stroke-width="1.2"/>\';\n    // Espada al costado\n    g += \'<rect x="79" y="8" width="3.4" height="30" fill="\'+P.claro+\'" stroke="\'+T+\'" stroke-width="1"/>\';\n    g += \'<path d="M80.7 2 L84 8 L77.4 8 Z" fill="\'+P.claro+\'" stroke="\'+T+\'" stroke-width="1"/>\';\n    g += \'<rect x="74" y="37" width="14" height="3.6" fill="\'+P.oro+\'" stroke="\'+T+\'" stroke-width="1"/>\';\n  } else if (valor === \'Q\'){\n    // Cabello largo\n    g += \'<path d="M31 8 L37 8 L37 34 L31 34 Z" fill="\'+P.suave+\'" stroke="\'+T+\'" stroke-width="1"/>\';\n    g += \'<path d="M63 8 L69 8 L69 34 L63 34 Z" fill="\'+P.suave+\'" stroke="\'+T+\'" stroke-width="1"/>\';\n    // Diadema\n    g += \'<path d="M34 6 L36 -2 L43 3.5 L50 -4 L57 3.5 L64 -2 L66 6 Z" fill="\'+P.oro+\'" stroke="\'+T+\'" stroke-width="1.2"/>\';\n    g += \'<rect x="34" y="5" width="32" height="4" fill="\'+P.oro+\'" stroke="\'+T+\'" stroke-width="1.2"/>\';\n    // Flor\n    g += \'<rect x="79.2" y="20" width="2.4" height="20" fill="\'+P.suave+\'"/>\';\n    g += \'<g fill="\'+P.fuerte+\'" stroke="\'+T+\'" stroke-width="1">\';\n    g += \'<circle cx="80.4" cy="11" r="5"/><circle cx="74" cy="16" r="4.2"/><circle cx="86.8" cy="16" r="4.2"/>\';\n    g += \'</g><circle cx="80.4" cy="14.5" r="2.6" fill="\'+P.oro+\'" stroke="\'+T+\'" stroke-width="1"/>\';\n  } else {\n    // Jota: casco con ala y lanza\n    g += \'<path d="M31 10 L37 10 L37 28 L31 28 Z" fill="\'+P.oro+\'" stroke="\'+T+\'" stroke-width="1"/>\';\n    g += \'<path d="M63 10 L69 10 L69 28 L63 28 Z" fill="\'+P.oro+\'" stroke="\'+T+\'" stroke-width="1"/>\';\n    g += \'<path d="M30 7 Q50 -6 70 7 L70 11 Q50 1 30 11 Z" fill="\'+P.suave+\'" stroke="\'+T+\'" stroke-width="1.2"/>\';\n    // Lanza\n    g += \'<rect x="79.4" y="12" width="2.8" height="28" fill="\'+P.oro+\'" stroke="\'+T+\'" stroke-width="1"/>\';\n    g += \'<path d="M80.8 2 L85 12 L76.6 12 Z" fill="\'+P.claro+\'" stroke="\'+T+\'" stroke-width="1"/>\';\n  }\n\n  return g;\n}\n\nfunction figuraCarta(valor,palo,rojo){\n  var col = colorPalo(palo);\n  // El rey de corazones es la carta de la casa: lleva la cara del juego\n  if (valor === \'K\' && palo === \'\\u2665\'){\n    return \'<svg class="medallon figura rey-casa" viewBox="0 0 100 100">\'+\n      \'<rect x="6" y="4" width="88" height="92" rx="3" fill="#fff" \'+\n        \'stroke="\'+col+\'" stroke-width="2"/>\'+\n      \'<image href="/cara.png" x="25" y="7" width="50" height="39" \'+\n        \'preserveAspectRatio="xMidYMid meet"/>\'+\n      \'<image href="/cara.png" x="25" y="54" width="50" height="39" \'+\n        \'preserveAspectRatio="xMidYMid meet" transform="rotate(180 50 73.5)"/>\'+\n      \'<line x1="6" y1="50" x2="94" y2="50" stroke="\'+col+\'" stroke-width="1.4"/>\'+\n      \'<text x="15" y="26" font-size="15" fill="\'+col+\'" text-anchor="middle" \'+\n        \'dominant-baseline="central">\\u2665</text>\'+\n      \'<text x="85" y="74" font-size="15" fill="\'+col+\'" text-anchor="middle" \'+\n        \'dominant-baseline="central">\\u2665</text>\'+\n      \'</svg>\';\n  }\n  var mitad = medioRetrato(valor,palo,col,rojo);\n  return \'<svg class="medallon figura" viewBox="0 0 100 100">\'+\n    \'<g>\'+mitad+\'</g><g transform="rotate(180 50 50)">\'+mitad+\'</g></svg>\';\n}\n/* Cada palo con su tono, para no confundir picas con treboles\n   ni corazones con diamantes de un vistazo */\nvar TONO = {\n  \'\\u2660\':\'#111111\',   // picas: negro pleno\n  \'\\u2663\':\'#1f5c33\',   // treboles: verde oscuro\n  \'\\u2665\':\'#d81f26\',   // corazones: rojo\n  \'\\u2666\':\'#e07a1f\'    // diamantes: naranja\n};\nfunction colorPalo(p){ return TONO[p] || \'#111\'; }\n\nfunction interiorCarta(c){\n  var rojo = esRoja(c.p);\n  var col = colorPalo(c.p);\n  var esq = \'<span class="esq ai"><b>\'+c.v+\'</b><i>\'+c.p+\'</i></span>\'+\n            \'<span class="esq bd"><b>\'+c.v+\'</b><i>\'+c.p+\'</i></span>\';\n  var centro;\n  if (\'JQK\'.indexOf(c.v) >= 0 && c.v.length === 1) centro = figuraCarta(c.v,c.p,rojo);\n  else if (c.v === \'A\') centro = \'<svg class="medallon as" viewBox="0 0 100 100">\'+asGrande(c.p,col)+\'</svg>\';\n  else centro = \'<svg class="medallon pips" viewBox="0 0 100 100">\'+simbolos(c.v,c.p,col)+\'</svg>\';\n  return esq + centro;\n}\nfunction htmlCarta(c,clase){\n  return \'<div class="\'+clase+\'" style="color:\'+colorPalo(c.p)+\'">\'+interiorCarta(c)+\'</div>\';\n}\n\n/* ═════ SELLO DE LA MANO ═════ */\nfunction selloDe(mano,triunfo){\n  var oro = \'#f7e6b8\', tachon = \'#b3202a\';\n  function svg(d){ return \'<svg viewBox="0 0 100 100">\'+d+\'</svg>\'; }\n  function tachado(){\n    return \'<line x1="13" y1="87" x2="87" y2="13" stroke="rgba(0,0,0,.55)" stroke-width="15" stroke-linecap="round"/>\'+\n           \'<line x1="13" y1="87" x2="87" y2="13" stroke="\'+tachon+\'" stroke-width="11" stroke-linecap="round"/>\'+\n           \'<line x1="13" y1="87" x2="87" y2="13" stroke="\'+oro+\'" stroke-width="4" stroke-linecap="round"/>\';\n  }\n  function texto(t,tam,y){\n    return \'<text x="50" y="\'+(y||53)+\'" font-size="\'+tam+\'" font-weight="700" fill="\'+oro+\'" \'+\n      \'text-anchor="middle" dominant-baseline="central" font-family="Georgia,serif" \'+\n      \'stroke="rgba(0,0,0,.45)" stroke-width="2" paint-order="stroke">\'+t+\'</text>\';\n  }\n  switch(mano.id){\n    case \'bazas\':\n      return svg(\'<g stroke="rgba(0,0,0,.4)" stroke-width="2">\'+\n        \'<rect x="18" y="26" width="26" height="38" rx="3" fill="\'+oro+\'" opacity=".6" transform="rotate(-18 31 45)"/>\'+\n        \'<rect x="37" y="24" width="26" height="40" rx="3" fill="\'+oro+\'" opacity=".8" transform="rotate(-2 50 44)"/>\'+\n        \'<rect x="55" y="26" width="26" height="38" rx="3" fill="\'+oro+\'" transform="rotate(16 68 45)"/>\'+\n        \'</g>\'+tachado());\n    case \'corazones\': return svg(texto(\'\\u2665\',62)+tachado());\n    case \'jk\':        return svg(texto(\'J\',48,38)+texto(\'K\',48,68)+tachado());\n    case \'qs\':        return svg(texto(\'Q\',62)+tachado());\n    case \'kh\':        return svg(texto(\'K\',52,42)+texto(\'\\u2665\',34,74)+tachado());\n    case \'ultimas\':   return svg(texto(\'2\',62)+tachado());\n    default:\n      if (triunfo){\n        var rojo = esRoja(triunfo);\n        return svg(\'<circle cx="50" cy="50" r="36" fill="rgba(255,255,255,.92)" stroke="\'+oro+\'" stroke-width="4"/>\'+\n          \'<text x="50" y="53" font-size="52" fill="\'+(rojo?\'#d81f26\':\'#141414\')+\'" \'+\n          \'text-anchor="middle" dominant-baseline="central">\'+triunfo+\'</text>\');\n      }\n      return svg(\'<circle cx="50" cy="50" r="34" fill="none" stroke="\'+oro+\'" stroke-width="4"/>\'+texto(\'\\u2605\',44));\n  }\n}\n\nfunction iniciales(n){\n  n = String(n||\'\').trim();\n  if (!n) return \'?\';\n  var p = n.split(/\\s+/);\n  return (p.length > 1 ? p[0].charAt(0)+p[1].charAt(0) : n.slice(0,2)).toUpperCase();\n}\n\n// Cada jugador se ve a sí mismo abajo; los demás rotan alrededor\nfunction puestoDe(sitio){\n  return PUESTOS[((sitio - miSitio) % 4 + 4) % 4];\n}\n\nfunction pintar(){\n  if (!estado) return;\n\n  if (!estado.empezada){\n    $(\'portada\').classList.add(\'oculto\');\n    $(\'espera\').classList.remove(\'oculto\');\n    pintarEspera();\n    return;\n  }\n\n  $(\'portada\').classList.add(\'oculto\');\n  $(\'espera\').classList.add(\'oculto\');\n  $(\'esquina\').classList.remove(\'oculto\');\n  $(\'mesa\').classList.remove(\'oculto\');\n\n  $(\'zona-mano\').classList.remove(\'oculto\');\n\n  // Si alguien recarga con la partida ya acabada, ve el podio otra vez\n  if (estado.terminada && !$(\'capa\')){\n    mostrarFinPartida(estado.marcador, estado.rondas || []);\n    return;\n  }\n\n  vigilarSonidos();\n  pintarSello();\n  pintarPuestos();\n  pintarCentro();\n  pintarMiMano();\n\n  if (estado.esperandoTriunfo === miSitio) pedirTriunfo();\n}\n\nfunction pintarEspera(){\n  $(\'codigo-mesa\').textContent = estado.codigo;\n  var html = \'\';\n  for (var i = 0; i < 4; i++){\n    var j = estado.jugadores[i];\n    if (j){\n      html += \'<div class="silla\'+(j.vacante ? \' vacante\' : \'\')+\'">\'+\n        \'<span class="num" style="background:\'+COLORES[i]+\'">\'+iniciales(j.nombre)+\'</span>\'+\n        \'<span class="quien">\'+(j.vacante ? j.nombre+\' (dej\\u00f3 la mesa)\' : j.nombre)+\'</span>\'+\n        (i === 0 ? \'<span class="marca">anfitrión</span>\' : \'\')+\n        (i === miSitio ? \'<span class="marca">tú</span>\' : \'\')+\n        \'</div>\';\n    } else {\n      html += \'<div class="silla vacia"><span class="num" style="background:rgba(255,255,255,.1)">\'+(i+1)+\'</span>\'+\n        \'<span class="quien">Esperando…</span></div>\';\n    }\n  }\n  $(\'lista-espera\').innerHTML = html;\n\n  var completos = estado.jugadores.length === 4;\n  if (miSitio === 0){\n    $(\'btn-empezar\').classList.toggle(\'oculto\', !completos);\n    $(\'aviso-espera\').classList.toggle(\'oculto\', completos);\n    $(\'aviso-espera\').textContent = \'Faltan \' + (4 - estado.jugadores.length) + \' jugadores\';\n  } else {\n    $(\'btn-empezar\').classList.add(\'oculto\');\n    $(\'aviso-espera\').classList.remove(\'oculto\');\n    $(\'aviso-espera\').textContent = completos\n      ? \'Esperando a que el anfitrión empiece…\'\n      : \'Faltan \' + (4 - estado.jugadores.length) + \' jugadores\';\n  }\n}\n\nvar mesaPrevia = 0, burlaHecha = \'\', recogiendo = \'\', yaCaidas = 0;\n/* Suena una carta al caer, un barrido al recogerse la baza,\n   y la burla si alguien carga con el rey de corazones en su mano */\nfunction vigilarSonidos(){\n  var n = estado.mesa.length;\n  if (n > mesaPrevia) ruidoCarta();\n  if (mesaPrevia === 4 && n === 0) ruidoRecoger();\n\n  // Solo en la mano del rey de corazones: en las demás el rey no cuesta nada\n  if (n === 4 && estado.ultimaBaza && estado.mano.id === \'kh\'){\n    var clave = estado.ronda + \'-\' + estado.iMano + \'-\' + estado.ultimaBaza.baza;\n    var rey = null;\n    estado.mesa.forEach(function(x){\n      if (x.carta.p === \'\\u2665\' && x.carta.v === \'K\') rey = x;\n    });\n    if (rey && burlaHecha !== clave){\n      burlaHecha = clave;\n      var g = estado.ultimaBaza.ganador;\n      var j = estado.jugadores[g] || { nombre:\'?\' };\n      setTimeout(function(){\n        // Si entretanto se pasó a otra mano, ya no viene a cuento\n        if (!estado || estado.mano.id !== \'kh\') return;\n        mostrarBurla(j.nombre, g === miSitio);\n      }, 260);\n    }\n  }\n\n  // Cuando están las cuatro, se dejan ver y luego viajan hacia quien gana\n  if (n === 4 && estado.ultimaBaza && recogiendo !== burlaHecha + \'|\' + estado.ultimaBaza.baza){\n    recogiendo = burlaHecha + \'|\' + estado.ultimaBaza.baza;\n    var haciaDonde = puestoDe(estado.ultimaBaza.ganador);\n    setTimeout(function(){\n      var centro = $(\'centro\');\n      if (centro) centro.classList.add(\'juntando\');\n    }, 1450);\n    setTimeout(function(){\n      var centro = $(\'centro\');\n      if (centro) centro.classList.add(\'recoge-\' + haciaDonde);\n    }, 1720);\n  }\n  if (n === 0){\n    var ce = $(\'centro\');\n    if (ce) ce.className = \'centro\';\n    yaCaidas = 0;\n  }\n  mesaPrevia = n;\n}\n\nfunction pintarSello(){\n  var s = $(\'sello\');\n  s.className = \'sello-mano \' + estado.mano.tipo;\n  s.innerHTML = selloDe(estado.mano, estado.triunfo);\n\n}\n\nvar PUESTOS_TXT = [\'\',\'1\\u00ba\',\'2\\u00ba\',\'3\\u00ba\',\'4\\u00ba\'];\nfunction fichaHtml(sitio){\n  var j = estado.jugadores[sitio] || { nombre:\'?\', conectado:false };\n  return \'<div class="ficha\'+(estado.turno === sitio ? \' turno\':\'\')+(j.conectado ? \'\' : \' caido\')+\'">\'+\n    \'<div class="avatar" style="background:\'+COLORES[sitio]+\'">\'+iniciales(j.nombre)+\'</div>\'+\n    \'<div class="ficha-txt" title="\'+j.nombre+\'">\'+\n      \'<div class="ficha-pts">\'+estado.puntosMano[sitio]+\' \\u00b7 T \'+estado.marcador[sitio]+\'</div>\'+\n    \'</div></div>\';\n}\n\nfunction pintarPuestos(){\n  [\'norte\',\'oeste\',\'este\'].forEach(function(p){ $(\'puesto-\'+p).innerHTML = \'\'; });\n  for (var s = 0; s < 4; s++){\n    if (s === miSitio) continue;\n    var donde = puestoDe(s);\n    $(\'puesto-\'+donde).innerHTML = fichaHtml(s);\n  }\n  $(\'tu-ficha\').innerHTML = fichaHtml(miSitio);\n}\n\nfunction pintarCentro(){\n  // Se amontonan en el centro: cada una entra desde su lado,\n  // ligeramente girada y encima de la anterior\n  var desvio = { sur:[5,78], oeste:[-56,10], norte:[-5,-78], este:[56,-10] };\n  var giro   = { sur:4, oeste:-8, norte:-3, este:8 };\n  var recienPuesta = estado.mesa.length;\n  $(\'centro\').innerHTML = estado.mesa.map(function(x, orden){\n    var nueva = (orden === recienPuesta - 1 && orden >= yaCaidas) ? \' entrando\' : \'\';\n    var donde = puestoDe(x.jugador);\n    var d = desvio[donde], g = giro[donde];\n    var gana = estado.ultimaBaza && estado.mesa.length === 4 &&\n               estado.ultimaBaza.ganador === x.jugador;\n    return \'<div class="jugada \'+donde+nueva+(gana ? \' ganadora\':\'\')+\'"\'+\n      \' style="z-index:\'+(gana ? 20 : orden + 2)+\n      \';transform:translate(calc(-50% + \'+d[0]+\'px),calc(-50% + \'+d[1]+\'px)) \'+\n      \'rotate(\'+g+\'deg)">\'+\n      htmlCarta(x.carta,\'carta\')+\n      (gana && estado.ultimaBaza.puntos ?\n        \'<span class="marca-pts \'+(estado.ultimaBaza.puntos > 0 ? \'mas\':\'menos\')+\'">\'+\n        (estado.ultimaBaza.puntos > 0 ? \'+\':\'\')+estado.ultimaBaza.puntos+\'</span>\' : \'\')+\n      \'</div>\';\n  }).join(\'\');\n  yaCaidas = estado.mesa.length;\n}\n\nfunction medidasMano(n, huecos){\n  // Se busca que de cada carta se vea una buena porcion, no solo el indice.\n  // Si hace falta, la carta se achica un poco para poder separarlas mas.\n  var escritorio = window.innerWidth >= 900;\n  var VISIBLE = 0.50;                       // parte de la carta que debe verse\n  var altoMax = escritorio ? 210 : 146;\n  var tope = escritorio ? 900 : 680;\n  var proporcion = escritorio ? 0.24 : 0.20;\n  var disponible = Math.min(window.innerWidth - 28, tope) - (huecos || 0) * 8;\n\n  var altoIdeal = Math.min(Math.round(window.innerHeight * proporcion), altoMax);\n  var anchoIdeal = Math.round(altoIdeal * 0.705);\n\n  // Con el tamano ideal, cuantas caben por fila mostrando lo que queremos\n  function cabenPorFila(ancho){\n    return Math.max(1, Math.floor((disponible - ancho) / (ancho * VISIBLE)) + 1);\n  }\n  var filas = (n > cabenPorFila(anchoIdeal)) ? 2 : 1;\n  var porFila = filas === 1 ? n : Math.ceil(n / 2);\n\n  // El ancho mayor que permite separar esa fila como queremos\n  var ancho = Math.floor(disponible / (1 + VISIBLE * (porFila - 1)));\n  if (ancho > anchoIdeal) ancho = anchoIdeal;\n  var alto = Math.round(ancho / 0.705);\n  if (alto > altoMax){ alto = altoMax; ancho = Math.round(alto * 0.705); }\n\n  var vis = porFila > 1 ? (disponible - ancho) / (porFila - 1) : ancho;\n  if (vis > ancho) vis = ancho;\n  return { filas:filas, porFila:porFila, ancho:ancho, alto:alto,\n           solape: Math.max(0, Math.round(ancho - vis)) };\n}\n\nfunction pintarMiMano(){\n  var cartas = estado.misCartas || [];\n  var puedo = estado.jugables || [];\n  function huecosEn(lista){\n    var h = 0;\n    for (var k = 1; k < lista.length; k++) if (lista[k-1].p !== lista[k].p) h++;\n    return h;\n  }\n  var m = medidasMano(cartas.length, huecosEn(cartas));\n  var cont = $(\'mi-mano\');\n  cont.style.setProperty(\'--ancho\', m.ancho+\'px\');\n  // La carta de la mesa, un punto mayor que la de la mano\n  document.documentElement.style.setProperty(\'--carta-mesa\', Math.round(m.ancho * 1.28)+\'px\');\n  cont.style.setProperty(\'--alto\', m.alto+\'px\');\n  cont.style.setProperty(\'--solape\', \'-\'+m.solape+\'px\');\n\n  function unaCarta(c, i, pos, total, anterior){\n    var texto = c.p + c.v;\n    var permitida = puedo.indexOf(texto) >= 0;\n    var miTurno = puedo.length > 0;\n    var clase = permitida ? \' jugable\' : (miTurno ? \' vetada\' : \'\');\n    var cambio = anterior && anterior.p !== c.p;\n    var centro = (total - 1) / 2;\n    var desvio = total > 1 ? (pos - centro) / centro : 0;\n    var giro = (desvio * 9).toFixed(1);\n    var caida = desvio * desvio * Math.min(total * 2.2, 20);\n    return \'<div class="carta-mano\'+clase+(cambio?\' nuevo-palo\':\'\')+\'"\'+\n      \' style="color:\'+colorPalo(c.p)+\';transform:rotate(\'+giro+\'deg) translateY(\'+caida.toFixed(1)+\'px)"\'+\n      (permitida ? \' onclick="tocarCarta(\\\'\'+texto+\'\\\')"\' : \'\')+\'>\'+interiorCarta(c)+\'</div>\';\n  }\n\n  if (m.filas === 1){\n    cont.className = \'mano\';\n    cont.innerHTML = \'<div class="fila">\'+\n      cartas.map(function(c,i){ return unaCarta(c,i,i,cartas.length,cartas[i-1]); }).join(\'\')+\'</div>\';\n  } else {\n    cont.className = \'mano dos-filas\';\n    var corte = m.porFila;\n    // Se busca un cambio de palo cerca del corte, sin desequilibrar las filas\n    var maxFila = m.porFila;\n    for (var d = 1; d <= 2; d++){\n      var a = m.porFila - d, b = m.porFila + d;\n      if (a > 1 && cartas.length - a <= maxFila &&\n          cartas[a] && cartas[a-1].p !== cartas[a].p){ corte = a; break; }\n      if (b < cartas.length && b <= maxFila &&\n          cartas[b] && cartas[b-1].p !== cartas[b].p){ corte = b; break; }\n    }\n    var sup = cartas.slice(0, corte), inf = cartas.slice(corte);\n    // El solape se ajusta a la fila mas larga para que ninguna se salga\n    var mayor = Math.max(sup.length, inf.length);\n    var huecosMax = Math.max(huecosEn(sup), huecosEn(inf));\n    var libre = Math.min(window.innerWidth - 28, window.innerWidth >= 900 ? 900 : 680)\n                - huecosMax * 8;\n    var visible = mayor > 1 ? (libre - m.ancho) / (mayor - 1) : m.ancho;\n    if (visible > m.ancho) visible = m.ancho;\n    cont.style.setProperty(\'--solape\', \'-\'+Math.max(0, Math.round(m.ancho - visible))+\'px\');\n    cont.innerHTML =\n      \'<div class="fila">\'+sup.map(function(c,k){ return unaCarta(c,k,k,sup.length,sup[k-1]); }).join(\'\')+\'</div>\'+\n      \'<div class="fila">\'+inf.map(function(c,k){ return unaCarta(c,k+corte,k,inf.length,inf[k-1]); }).join(\'\')+\'</div>\';\n  }\n  if (elegida) marcarElegida();\n}\n\nvar elegida = null, tiempoElegida = 0;\n/* El primer toque levanta la carta; el segundo la suelta.\n   Así no se juega una carta por un roce. */\nfunction tocarCarta(texto){\n  if (elegida === texto){\n    elegida = null;\n    jugar(texto);\n    return;\n  }\n  elegida = texto;\n  tiempoElegida = Date.now();\n  marcarElegida();\n  // Si no se confirma, se baja sola\n  setTimeout(function(){\n    if (elegida === texto && Date.now() - tiempoElegida >= 2900){\n      elegida = null; marcarElegida();\n    }\n  }, 3000);\n}\nfunction marcarElegida(){\n  var cartas = $(\'mi-mano\').querySelectorAll(\'.carta-mano\');\n  var lista = estado ? estado.misCartas : [];\n  for (var i = 0; i < cartas.length; i++){\n    var c = lista[i];\n    var suya = c && (c.p + c.v) === elegida;\n    cartas[i].classList.toggle(\'elegida\', !!suya);\n  }\n}\nfunction jugar(texto){\n  elegida = null;\n  enviar({ tipo:\'jugar\', carta: texto });\n}\n\n/* ═════ ELEGIR TRIUNFO ═════ */\nvar pidiendoTriunfo = false;\nfunction pedirTriunfo(){\n  if (pidiendoTriunfo) return;\n  pidiendoTriunfo = true;\n  var cuenta = {};\n  PALOS.forEach(function(p){ cuenta[p] = 0; });\n  (estado.misCartas || []).forEach(function(c){ cuenta[c.p]++; });\n  var sugerido = PALOS.slice().sort(function(a,b){ return cuenta[b] - cuenta[a]; })[0];\n  capa(\n    \'<h2>Tu triunfo</h2><p class="sub">Elige el palo que mande en esta mano</p>\'+\n    \'<div class="palos-elegir">\'+PALOS.map(function(p){\n      return \'<button class="palo-op\'+(esRoja(p)?\' roja\':\'\')+(p===sugerido?\' mejor\':\'\')+\'" \'+\n        \'onclick="fijarTriunfo(\\\'\'+p+\'\\\')"><b>\'+p+\'</b><span>\'+cuenta[p]+\' cartas</span></button>\';\n    }).join(\'\')+\'</div>\'\n  );\n}\nfunction fijarTriunfo(p){\n  pidiendoTriunfo = false;\n  quitarCapa();\n  enviar({ tipo:\'triunfo\', palo: p });\n}\n\n/* ═════ MENSAJES DE MANO Y RONDA ═════ */\nfunction mostrarPuntosMano(puntos){\n  for (var s = 0; s < 4; s++){\n    (function(k){\n      setTimeout(function(){\n        var caja = (k === miSitio) ? $(\'tu-ficha\') : $(\'puesto-\'+puestoDe(k));\n        if (!caja) return;\n        var v = puntos[k];\n        caja.insertAdjacentHTML(\'beforeend\',\n          \'<div class="puntos-mano \'+(v>0?\'suma\':v<0?\'resta\':\'cero\')+\'">\'+\n          (v>0?\'+\':\'\')+v+\'</div>\');\n        setTimeout(function(){\n          var e = caja.querySelector(\'.puntos-mano\');\n          if (e) e.parentNode.removeChild(e);\n        }, 1900);\n      }, k * 140);\n    })(s);\n  }\n}\n\nfunction mostrarFinRonda(marcador){\n  var orden = [0,1,2,3].sort(function(a,b){ return marcador[b] - marcador[a]; });\n  var medallas = [\'\\u{1F947}\',\'\\u{1F948}\',\'\\u{1F949}\',\'\\u{1F3C5}\'];\n  capa(\n    \'<h2>Ronda terminada</h2><p class="sub">Las diez manos completas</p>\'+\n    \'<table class="tabla"><tbody>\'+orden.map(function(s,i){\n      var j = estado.jugadores[s] || {nombre:\'?\'};\n      return \'<tr><td>\'+medallas[i]+\' \'+j.nombre+\'</td>\'+\n        \'<td class="\'+(marcador[s]<0?\'neg\':\'pos\')+\'">\'+(marcador[s]>0?\'+\':\'\')+marcador[s]+\'</td></tr>\';\n    }).join(\'\')+\'</tbody></table>\'+\n    \'<button class="btn" onclick="quitarCapa()">Seguir jugando</button>\'\n  );\n}\n\n/* Repasar la baza anterior */\nfunction verUltimaBaza(){\n  var u = estado && estado.ultimaBaza;\n  if (!u || !u.cartas || !u.cartas.length){\n    capa(\'<h2>Todavía nada</h2><p class="sub">Aún no se ha cerrado ninguna baza</p>\'+\n         \'<button class="btn" onclick="quitarCapa()">Volver</button>\');\n    return;\n  }\n  var cartas = u.cartas.map(function(x){\n    var j = estado.jugadores[x.jugador] || {nombre:\'?\'};\n    var gana = x.jugador === u.ganador;\n    return \'<div class="baza-item\'+(gana?\' gano\':\'\')+\'">\'+\n      \'<div class="baza-quien">\'+j.nombre+\'</div>\'+\n      htmlCarta(x.carta,\'carta\')+\n      \'<div class="baza-sello">\'+(gana ? \'se la llevó\' : \'&nbsp;\')+\'</div>\'+\n      \'</div>\';\n  }).join(\'\');\n  var quien = estado.jugadores[u.ganador] || {nombre:\'?\'};\n  capa(\n    \'<h2>Última baza</h2>\'+\n    \'<p class="sub">\'+estado.mano.nom+\' · baza \'+u.baza+\n      (u.puntos ? \' · \'+(u.puntos>0?\'+\':\'\')+u.puntos+\' para \'+quien.nombre : \'\')+\'</p>\'+\n    \'<div class="baza-repaso">\'+cartas+\'</div>\'+\n    \'<button class="btn" onclick="quitarCapa()">Seguir jugando</button>\'\n  );\n}\n\n/* Cuatro botones, uno por ronda, para repasar cada marcador */\nfunction botonesRondas(){\n  var rondas = estado.rondas || [];\n  var html = \'<p class="sub" style="margin:16px 0 8px">Resumen por ronda</p>\'+\n    \'<div class="botones-ronda">\';\n  for (var r = 1; r <= 4; r++){\n    var jugada = rondas.some(function(x){ return x.ronda === r; });\n    var enCurso = (r === estado.ronda);\n    html += \'<button class="btn-ronda\'+(jugada?\' jugada\':\'\')+(enCurso?\' actual\':\'\')+\'"\'+\n      (jugada||enCurso ? \' onclick="verRonda(\'+r+\')"\' : \' disabled\')+\n      \'>R\'+r+\'<span>\'+(jugada?\'ver\':(enCurso?\'en curso\':\'\\u2014\'))+\'</span></button>\';\n  }\n  return html + \'</div>\';\n}\n\n/* El marcador de una ronda concreta */\nfunction verRonda(r){\n  var rondas = estado.rondas || [];\n  var datos = null;\n  rondas.forEach(function(x){ if (x.ronda === r) datos = x; });\n  var enCurso = !datos && r === estado.ronda;\n  var puntos = datos ? datos.puntos : estado.marcador;\n  var orden = [0,1,2,3].slice().sort(function(a,b){ return puntos[b] - puntos[a]; });\n  var medallas = [\'\\u{1F947}\',\'\\u{1F948}\',\'\\u{1F949}\',\'\\u{1F3C5}\'];\n  capa(\n    \'<h2>Ronda \'+r+\'</h2>\'+\n    \'<p class="sub">\'+(enCurso ? \'Va por la mano \'+(estado.iMano+1)+\' de 10\'\n                                : \'Ronda terminada\')+\'</p>\'+\n    \'<table class="tabla"><tbody>\'+orden.map(function(s,i){\n      var j = estado.jugadores[s] || {nombre:\'?\'};\n      return \'<tr><td>\'+medallas[i]+\' \'+j.nombre+\'</td>\'+\n        \'<td class="\'+(puntos[s]<0?\'neg\':\'pos\')+\'">\'+(puntos[s]>0?\'+\':\'\')+puntos[s]+\'</td></tr>\';\n    }).join(\'\')+\'</tbody></table>\'+\n    \'<button class="btn gris" onclick="verMarcador()">Volver al marcador</button>\'+\n    \'<button class="btn" onclick="quitarCapa()">Seguir jugando</button>\'\n  );\n}\n\nvar EXPLICA = {\n  bazas:     \'Cada baza que te lleves resta 20\',\n  corazones: \'Cada corazón resta 20\',\n  jk:        \'Cada J y cada K restan 30\',\n  qs:        \'Cada dama resta 50\',\n  kh:        \'Llevarte el rey de corazones resta 160\',\n  ultimas:   \'Las dos últimas bazas restan 90 cada una\'\n};\n\n/* Cierre de la partida: podio y opción de revancha */\nfunction mostrarFinPartida(marcador, rondas){\n  var orden = [0,1,2,3].slice().sort(function(a,b){ return marcador[b] - marcador[a]; });\n  var medallas = [\'\\u{1F947}\',\'\\u{1F948}\',\'\\u{1F949}\',\'\\u{1F3C5}\'];\n  var campeon = estado.jugadores[orden[0]] || {nombre:\'?\'};\n  capa(\n    \'<div class="corona">\\u{1F3C6}</div>\'+\n    \'<h2>\'+campeon.nombre+\'</h2>\'+\n    \'<p class="sub">Gana la partida tras \'+(rondas||[]).length+\' rondas</p>\'+\n    \'<table class="tabla"><tbody>\'+orden.map(function(s,i){\n      var j = estado.jugadores[s] || {nombre:\'?\'};\n      return \'<tr\'+(i===0?\' class="campeon"\':\'\')+\'><td>\'+medallas[i]+\' \'+j.nombre+\'</td>\'+\n        \'<td class="\'+(marcador[s]<0?\'neg\':\'pos\')+\'">\'+(marcador[s]>0?\'+\':\'\')+marcador[s]+\'</td></tr>\';\n    }).join(\'\')+\'</tbody></table>\'+\n    (miSitio === 0\n      ? \'<button class="btn" onclick="revancha()">Otra partida</button>\'\n      : \'<p class="sub">Esperando al anfitrión…</p>\')+\n    \'<button class="btn gris" onclick="salirMesa()">Salir de la mesa</button>\'\n  );\n}\nfunction revancha(){ quitarCapa(); enviar({ tipo:\'revancha\' }); }\n\n/* Dejar la mesa */\nfunction salirMesa(){\n  capa(\n    \'<h2>\\u00bfDejar la mesa?</h2>\'+\n    \'<p class="sub">Tu sitio queda libre y otro puede ocuparlo</p>\'+\n    \'<button class="btn gris" onclick="confirmarSalida()">S\\u00ed, salir</button>\'+\n    \'<button class="btn" onclick="quitarCapa()">Seguir jugando</button>\'\n  );\n}\nfunction confirmarSalida(){\n  enviar({ tipo:\'salir\' });\n  try { localStorage.removeItem(\'king_mesa\'); } catch(e){}\n  setTimeout(function(){ location.reload(); }, 200);\n}\n\nfunction verMarcador(){\n  if (!estado || !estado.empezada) return;\n  var m = estado.mano;\n  var nombreMano = m.tipo === \'pos\'\n    ? (\'Triunfo de \' + ((estado.jugadores[m.dueno]||{}).nombre || \'?\') +\n       (estado.triunfo ? \'  \' + estado.triunfo : \'\'))\n    : m.nom;\n  var explica = m.tipo === \'pos\'\n    ? \'Cada baza suma 25\'\n    : (EXPLICA[m.id] || \'\');\n  capa(\n    \'<h2>Marcador</h2><p class="sub">Ronda \'+estado.ronda+\' · mano \'+(estado.iMano+1)+\' de 10</p>\'+\n    \'<div class="mano-actual-info">\'+\n      \'<div class="mano-nombre">\'+nombreMano+\'</div>\'+\n      \'<div class="mano-explica">\'+explica+\'</div>\'+\n    \'</div>\'+\n    \'<table class="tabla"><tbody>\'+[0,1,2,3].map(function(s){\n      var j = estado.jugadores[s] || {nombre:\'?\'};\n      return \'<tr><td>\'+j.nombre+\'</td>\'+\n        \'<td class="\'+(estado.marcador[s]<0?\'neg\':\'pos\')+\'">\'+\n        (estado.marcador[s]>0?\'+\':\'\')+estado.marcador[s]+\'</td></tr>\';\n    }).join(\'\')+\'</tbody></table>\'+\n    botonesRondas()+\n    \'<p class="sub">Código de la mesa: <b>\'+estado.codigo+\'</b></p>\'+\n    \'<button class="btn" onclick="quitarCapa()">Seguir jugando</button>\'+\n    \'<button class="btn gris" onclick="salirMesa()">Salir de la mesa</button>\'\n  );\n}\n\n/* ═════ CAPAS ═════ */\nfunction capa(html){\n  quitarCapa();\n  var el = document.createElement(\'div\');\n  el.className = \'portada\';\n  el.id = \'capa\';\n  el.innerHTML = \'<div class="panel">\'+html+\'</div>\';\n  document.body.appendChild(el);\n}\nfunction quitarCapa(){\n  var el = $(\'capa\');\n  if (el) el.parentNode.removeChild(el);\n}\n\nwindow.addEventListener(\'resize\', function(){ if (estado && estado.empezada) pintarMiMano(); });\n\n/* Si veníamos de una mesa, se vuelve a entrar sola */\n(function(){\n  var mesaPrevia = localStorage.getItem(\'king_mesa\');\n  var nombre = localStorage.getItem(\'king_nombre\');\n  if (mesaPrevia && nombre){\n    codigoActual = mesaPrevia;\n    conectar(function(){\n      enviar({ tipo:\'entrar\', codigo: mesaPrevia, id: MI_ID, nombre: nombre });\n    });\n  }\n})();\n</script>\n</body>\n</html>\n';
